WITH flattened AS (SELECT id, log_ts, level, status_code, k, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, value) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, PERCENTILE_APPROX(status_code, ARRAY(0.25, 0.5, 0.75)) AS status_code_quartiles, SIZE(COLLECT_SET(level)) AS num_levels, SIZE(COLLECT_SET(level)) AS num_levels_2, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS span_minutes, SUM(CASE WHEN k = 'version' THEN status_code ELSE 0 END) AS version_status_code FROM flattened GROUP BY DATE_TRUNC('DAY', log_ts) ORDER BY num_levels_2 DESC
